"""s24 (site v3, TEAM-10): the gap model. New: site/gaps_spec.json, site/deliverables.json, site/gapkit.py, tests/test_site_v3.py. Edits: site/registry.py (appended block), tracker/snapshot.py (markdown tables), site/build.py (gap-model checks, private paths), tracker/catalogue.py (TEAM-10..12). Apply after p25 and the S23 site patch; then s25-s28."""
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
MARK = '# ---- s24 (site v3 data layer'


def read(rel):
    return (ROOT / rel).read_text(encoding="utf-8")


def write(rel, text):
    (ROOT / rel).write_text(text, encoding="utf-8", newline="\n")


def replace_once(rel, old, new):
    t = read(rel)
    n = t.count(old)
    assert n == 1, "%s: anchor found %d times (expected once): %r" % (rel, n, old[:80])
    write(rel, t.replace(old, new, 1))


def new_file(rel, text):
    p = ROOT / rel
    assert not p.exists(), "%s already exists" % rel
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(text, encoding="utf-8", newline="\n")


def require(rel, marker, why):
    assert marker in read(rel), why


assert MARK not in read('site/registry.py'), "already applied: %r found in %s" % (MARK, 'site/registry.py')

require("tracker/catalogue.py", "# ---- overrides p25", "apply p25 (wave A) first")
require("site/build.py", "def literal_errors", "apply the S23 site patch (wave A kit) first")

